examples.template:
MonarchButton({{trigger}}, variant: .primary) { isPresented = true }
    .sheet(isPresented: $isPresented) {
        NavigationStack {
            ScrollView {
                VStack(alignment: .leading, spacing: theme.spacing.space4) {
                    MonarchTextField({{name.label}}, text: $name, prompt: {{name.value}}, error: nameError, isRequired: true)
                    MonarchUsernameAvailabilityInput(
                        {{username.label}},
                        text: $username,
                        prompt: {{username.prompt}},
                        helper: {{username.helper}},
                        prefix: {{username.prefix}},
                        isRequired: true,
                        onStatusChange: { status, _ in usernameStatus = status },
                        validate: { handle in await Self.checkUsername(handle) }
                    )
                    MonarchRadioCardGroup(
                        {{type.label}},
                        selection: $type,
                        options: [
                            MonarchRadioCardOption({{type.options.0.id}}, title: {{type.options.0.title}}, description: {{type.options.0.description}}, systemImage: "person"),
                            MonarchRadioCardOption({{type.options.1.id}}, title: {{type.options.1.title}}, description: {{type.options.1.description}}, systemImage: "building.2"),
                        ],
                        columns: 2,
                        compactColumns: 2
                    )
                    MonarchButton({{submit}}, variant: .primary, isLoading: isCreating, fullWidth: true) {
                        hasSubmitted = true
                        guard nameError == nil, type != nil, usernameStatus == .valid else { return }
                        isCreating = true
                        // Create the workspace, then set isCreating to false and isPresented to false.
                    }
                }
                .monarchHelperAbove()
                .padding(theme.spacing.space4)
            }
            .navigationTitle({{title}})
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button({{cancel}}) { isPresented = false }
                        .disabled(isCreating)
                }
            }
        }
        .interactiveDismissDisabled(isCreating)
    }

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var isPresented = false
@State private var name = {{name.value}}
@State private var username = ""
@State private var type: String? = {{type.value}}
@State private var usernameStatus = MonarchUsernameAvailabilityStatus.idle
@State private var hasSubmitted = false
@State private var isCreating = false

private var nameError: String? {
    let count = name.trimmingCharacters(in: .whitespacesAndNewlines).count
    guard hasSubmitted || count > 0 else { return nil }
    if count < 4 { return "Name must be at least 4 characters" }
    if count > 25 { return "Name must be at most 25 characters" }
    return nil
}

nonisolated private static func checkUsername(_ handle: String) async -> MonarchUsernameAvailabilityResult? {
    guard !handle.isEmpty else { return nil }
    // Call the product's availability lookup here.
    return handle.lowercased() == {{username.taken}}
        ? MonarchUsernameAvailabilityResult(isValid: false, message: {{username.takenMessage}})
        : MonarchUsernameAvailabilityResult(isValid: true)
}

